def make_point(x, y):
    return {'x': x, 'y': y}


def make_rect(x, y, w, h):
    return {'x': x, 'y': y, 'width': w, 'height': h}


def distance(p1, p2):
    return ((p1['x'] - p2['x'])**2 + (p1['y'] - p2['y'])**2) ** 0.5


def rect_area(r):
    return r['width'] * r['height']


def rect_contains(r, p):
    return r['x'] <= p['x'] <= r['x'] + r['width'] and r['y'] <= p['y'] <= r['y'] + r['height']
